    var end = new Date(reliableEventAt(endAt) ? Number(endAt) : start.getTime());
    var sameDay = start.getFullYear() === end.getFullYear()
      && start.getMonth() === end.getMonth()
      && start.getDate() === end.getDate();
    if (sameDay) {
      var startPart = dayPart(start.getHours());
      var endPart = dayPart(end.getHours());
      return formatDay(start.getTime()) + (startPart === endPart ? startPart : startPart + "至" + endPart);
    }
    return formatDay(start.getTime()) + "至" + formatDay(end.getTime());
