    "今天晴天": true,
    "今天阴天": true,
    "今天下雨": true,
    "今天下雪": true,
    "早安": true,
    "晚安": true,
    "你好": true,
    "收到": true,
    "好的": true,
    "打开页面": true,
    "打开了页面": true,
